import { createResponsesSession } from "@katalon-experiments/ai-client/responses-session";
import { randomBytes } from "node:crypto";
import { mkdtemp, readFile, readdir, stat } from "node:fs/promises";
import { tmpdir } from "node:os";
import { isAbsolute, join } from "node:path";
import { requestComputerActionTurn } from "@katalon-experiments/ai-client/agents";
import { AppiumDesktop } from "./appium.mjs";
import {
  privateDirectory,
  privateFile,
  redactSecrets,
  sha256,
} from "./private.mjs";

const model = "gpt-6.1-terra";
const now = () => new Date().toISOString();
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

class DesktopTransportFailure extends Error {}

function validate(config) {
  if (process.platform !== "darwin") throw new Error("macOS host required");
  if (!config || typeof config !== "object")
    throw new TypeError("Configuration required");
  if (config.model !== undefined && config.model !== "gpt-6.1-terra")
    throw new TypeError("Only the supported Terra Runner model is available");
  if (
    config.reasoning !== undefined &&
    !["low", "medium"].includes(config.reasoning)
  )
    throw new TypeError("Runner reasoning must be low or medium");
  if (typeof config.scenario !== "string" || !config.scenario.trim())
    throw new TypeError("Nonempty scenario required");
  if (
    typeof config.requestAI !== "function" &&
    (typeof config.apiKey !== "string" || !config.apiKey)
  )
    throw new TypeError("Host-provided API key required");
  if (
    typeof config.app !== "string" ||
    config.app.length > 200 ||
    !config.app.includes(".") ||
    !config.app.split(".").every((part) => /^[A-Za-z0-9-]+$/.test(part))
  )
    throw new TypeError("Target app bundle ID required");
  if (config.outputDir && !isAbsolute(config.outputDir))
    throw new TypeError("Absolute outputDir required");
  if (
    config.parameters === null ||
    typeof (config.parameters ?? {}) !== "object" ||
    Array.isArray(config.parameters)
  )
    throw new TypeError("Named scalar parameters required");
  for (const [name, value] of Object.entries(config.parameters ?? {}))
    if (
      !name ||
      !["string", "number", "boolean"].includes(typeof value) ||
      (typeof value === "number" && !Number.isFinite(value))
    )
      throw new TypeError("Named scalar parameters required");
  if (config.launch !== undefined && typeof config.launch !== "boolean")
    throw new TypeError("target.launch must be boolean");
  for (const [name, maximum] of [
    ["calls", 80],
    ["desktopInputs", 150],
    ["ms", 600000],
  ]) {
    const value = config.limits?.[name];
    if (
      value !== undefined &&
      (!Number.isInteger(value) || value < 1 || value > maximum)
    )
      throw new TypeError(`limits.${name} must be between 1 and ${maximum}`);
  }
}

// GPT-6.1 Terra standard rates, 30-minute cache, checked 2026-10-30:
// https://developers.openai.com/api/docs/models/gpt-6.1-terra
function estimateCost(usage) {
  const input = usage.input_tokens ?? 0;
  const output = usage.output_tokens ?? 0;
  const cached = usage.input_tokens_details?.cached_tokens ?? 0;
  const written = usage.input_tokens_details?.cache_write_tokens ?? 0;
  return (
    ((Math.max(0, input - cached - written) * 1 +
      cached * 0.05 +
      written * 1.25) *
      (input > 272000 ? 2 : 1) +
      output * 5 * (input > 272000 ? 1.5 : 1)) /
    1e6
  );
}

function initialDesktopActionInput({ scenario, parameters, app, imageUrl }) {
  return [
    {
      role: "system",
      content:
        "Operate the supplied app on the local macOS desktop. Use the computer tool for UI actions. " +
        "Follow the scenario and report the visible result truthfully.",
    },
    {
      role: "user",
      content: [
        {
          type: "input_text",
          text: JSON.stringify({
            scenario,
            parameters,
            target: { app },
            previousDesktopActions: [],
            platform: "macOS",
          }),
        },
        {
          type: "input_image",
          image_url: imageUrl,
          detail: "original",
        },
      ],
    },
  ];
}

function buildDesktopActionRequest({ input, previous, effort }) {
  return {
    model,
    tools: [
      { type: "computer" },
      {
        type: "function",
        name: "inspect_accessibility",
        description:
          "Read fresh Accessibility text for the target app. It may be incomplete.",
        parameters: {
          type: "object",
          properties: {},
          additionalProperties: false,
        },
        strict: true,
      },
    ],
    reasoning: { effort },
    max_output_tokens: 3000,
    prompt_cache_options: { mode: "implicit", ttl: "30m" },
    input,
    ...(previous ? { previous_response_id: previous } : {}),
  };
}

/** Run one scenario in a local macOS app. Artifacts remain private. */
export async function runScenario(config) {
  validate(config);
  const out =
    config.outputDir ?? (await mkdtemp(join(tmpdir(), "loki-mac-runner-")));
  await privateDirectory(out);
  if ((await readdir(out)).length)
    throw new Error("Artifact directory must be empty");
  const save = (name, value) => privateFile(join(out, name), value);
  let sessionEvent = 0;
  const providerSession = createResponsesSession({
    apiKey: config.apiKey,
    requestAI: config.requestAI,
    record: (event) => save(`provider-session-${++sessionEvent}.json`, event),
  });
  const parameters = config.parameters ?? {};
  const secretNames = new Set([
    ...(config.secretParameterNames ?? []),
    ...Object.keys(parameters).filter((name) =>
      /pass(word)?|token|secret|api.?key|email/i.test(name),
    ),
  ]);
  const redact = redactSecrets([
    config.apiKey,
    ...[...secretNames].map((name) => parameters[name]),
  ]);
  const taskId = config.taskId ?? randomBytes(8).toString("hex");
  const limits = {
    calls: config.limits?.calls ?? 80,
    desktopInputs: config.limits?.desktopInputs ?? 150,
    ms: config.limits?.ms ?? 600000,
  };
  const started = Date.now();
  const operatorSignal = config.signal;
  config = {
    ...config,
    signal: AbortSignal.any([
      AbortSignal.timeout(limits.ms),
      ...(operatorSignal ? [operatorSignal] : []),
    ]),
  };
  const calls = [],
    actions = [],
    axReads = [],
    frames = [];
  const usage = {
    inputTokens: 0,
    outputTokens: 0,
    cachedTokens: 0,
    cacheWriteTokens: 0,
  };
  let desktop,
    captureContext,
    terminal = { actor: "harness", reason: "not-started" };
  let attempts = 0,
    estimatedCost = 0;
  let summary;
  const progress = (event) => {
    try {
      config.onProgress?.(redact.value(event));
    } catch {
      /* observation only */
    }
  };
  const check = () => {
    if (operatorSignal?.aborted) throw new Error("Operator Stop");
    config.signal.throwIfAborted();
    if (Date.now() - started > limits.ms) throw new Error("Time limit");
  };
  const capture = async (name) => {
    check();
    const { bytes, frame } = await desktop.capture();
    captureContext = frame;
    await save(name, bytes);
    frames.push({ screenshot: name, at: now(), ...frame });
    await save("frames.json", frames);
    return {
      type: "computer_screenshot",
      image_url: `data:image/png;base64,${bytes.toString("base64")}`,
      detail: "original",
    };
  };
  const execute = async (action, call, callId) => {
    check();
    if (
      !["wait", "screenshot"].includes(action.type) &&
      actions.filter(
        (row) =>
          row.status === "returned" &&
          !["wait", "screenshot"].includes(row.action.type),
      ).length >= limits.desktopInputs
    )
      throw Error("Desktop input limit");
    const row = {
      index: actions.length + 1,
      providerCall: call,
      callId,
      action: redact.value(action),
      status: "invoked",
      startedAt: now(),
    };
    actions.push(row);
    await save("actions.json", actions);
    try {
      row.geometry = captureContext;
      await desktop.execute(action);
      row.status = "returned";
    } catch (error) {
      row.status = "error";
      row.error = redact.text(String(error));
    } finally {
      row.endedAt = now();
      await save("actions.json", actions);
    }
    return row;
  };
  async function dispatchDesktopRequest(request, number) {
    const callStarted = Date.now();
    let response;
    try {
      const timeout = AbortSignal.timeout(120000);
      const requestSignal = config.signal
        ? AbortSignal.any([timeout, config.signal])
        : timeout;
      // Host-supplied transport only. Request construction, model, execution
      // and response handling remain owned by Runner. No automatic fallback.
      response = await providerSession.send(request, requestSignal);
    } catch (error) {
      // A send failure is distinct from a malformed returned response.
      terminal = {
        actor: operatorSignal?.aborted ? "operator" : "transport",
        reason: redact.text(String(error)),
        call: number,
      };
      await save("transport-failure.json", terminal);
      throw new DesktopTransportFailure();
    }
    const transport = {
      call: number,
      at: now(),
      durationMs: Date.now() - callStarted,
      httpStatus: response.status,
      requestId: response.headers.get("x-request-id"),
    };
    await save(`transport-${number}.json`, transport);
    const bodyText = await response.text();
    await save(`response-${number}.json`, bodyText);
    let body;
    try {
      body = JSON.parse(bodyText);
    } catch {
      throw new Error("Provider returned invalid JSON");
    }
    const bill = body.usage ?? null;
    const cost = bill ? estimateCost(bill) : null;
    if (cost !== null) estimatedCost += cost;
    if (bill) {
      usage.inputTokens += bill.input_tokens ?? 0;
      usage.outputTokens += bill.output_tokens ?? 0;
      usage.cachedTokens += bill.input_tokens_details?.cached_tokens ?? 0;
      usage.cacheWriteTokens +=
        bill.input_tokens_details?.cache_write_tokens ?? 0;
    }
    calls.push({
      call: number,
      status: response.ok ? body.status : `HTTP ${response.status}`,
      durationMs: Date.now() - callStarted,
      usage: bill,
      estimatedCost: cost,
      requestId: transport.requestId,
      outputs: body.output?.map((item) => item.type) ?? [],
    });
    await save("calls.json", calls);
    progress({
      call: number,
      status: calls.at(-1).status,
      estimatedCost: cost,
    });
    return { response, body, transport };
  }
  try {
    check();
    desktop = new AppiumDesktop({
      outputDir: out,
      app: config.app,
      launch: config.launch,
      signal: config.signal,
    });
    await desktop.start();
    check();
    await save("target.json", {
      app: config.app,
      platform: "macOS",
      backend: "Appium Mac2",
      display: "main",
    });
    const initial = await capture("screen-initial.png");
    let input = initialDesktopActionInput({
      scenario: config.scenario,
      parameters,
      app: config.app,
      imageUrl: initial.image_url,
    });
    let previous;
    for (let number = 1; number <= limits.calls; number++) {
      check();
      const request = buildDesktopActionRequest({
        input,
        previous,
        effort: config.reasoning ?? "low",
      });
      request.store = false;
      await save(`request-${number}.json`, request);
      attempts = number;
      let turn;
      try {
        // The desktop transport owns cancellation. Retain a response returned
        // during Stop before the existing host checks the next physical input.
        turn = await requestComputerActionTurn({
          request,
          dispatch: () => dispatchDesktopRequest(request, number),
        });
      } catch (error) {
        if (error instanceof DesktopTransportFailure) break;
        throw error;
      }
      const { response, body, transport } = turn;
      if (!response.ok || body.status !== "completed") {
        terminal = {
          actor: "API",
          reason: response.ok ? body.status : `HTTP ${response.status}`,
          call: number,
          requestId: transport.requestId,
        };
        break;
      }
      const computer =
        body.output?.filter((item) => item.type === "computer_call") ?? [];
      const functions =
        body.output?.filter((item) => item.type === "function_call") ?? [];
      if (!computer.length && !functions.length) {
        terminal = {
          actor: "model",
          reason: "No further desktop actions",
          answer: redact.text(
            body.output
              ?.filter((item) => item.type === "message")
              .flatMap((item) => item.content ?? [])
              .map((item) => item.text ?? "")
              .join("\n"),
          ),
        };
        break;
      }
      input = [];
      for (const item of body.output ?? []) {
        if (item.type === "computer_call") {
          if (item.pending_safety_checks?.length) {
            terminal = {
              actor: "API safety check",
              reason: "Pending safety checks",
            };
            break;
          }
          const errors = [];
          let screen;
          for (const action of item.actions ?? []) {
            const row = await execute(action, number, item.call_id);
            await delay(250);
            screen = await capture(`screen-action-${row.index}.png`);
            if (row.status === "error") {
              errors.push(row.error);
              break;
            }
          }
          screen ??= await capture(`screen-${number}.png`);
          input.push({
            type: "computer_call_output",
            call_id: item.call_id,
            output: screen,
          });
          if (errors.length)
            input.push({
              role: "user",
              content: `The last desktop input was not confirmed: ${errors.join("; ")}. Inspect the fresh screenshot before deciding another action.`,
            });
        } else if (item.type === "function_call") {
          if (item.name !== "inspect_accessibility")
            throw new Error("Unexposed tool requested");
          check();
          let text,
            isError = false;
          try {
            text = await desktop.inspect();
          } catch (error) {
            isError = true;
            text = redact.text(String(error));
          }
          axReads.push({ call: number, at: now(), isError, text });
          await save("ax-reads.json", axReads);
          input.push({
            type: "function_call_output",
            call_id: item.call_id,
            output: isError ? `Accessibility unavailable: ${text}` : text,
          });
        }
      }
      if (terminal.actor === "API safety check") break;
      previous = body.id;
      if (number === limits.calls)
        terminal = { actor: "harness", reason: "API call limit" };
    }
  } catch (error) {
    terminal = {
      actor: operatorSignal?.aborted ? "operator" : "harness",
      reason: redact.text(String(error)),
    };
    await save("error.json", terminal);
  } finally {
    providerSession?.close();
    let cleanup = { sessionDeleted: true, processClosed: true, errors: [] };
    if (desktop) {
      try {
        cleanup = await desktop.close();
      } catch (error) {
        cleanup = {
          sessionDeleted: false,
          processClosed: false,
          errors: [redact.text(String(error))],
        };
      }
    }
    await save("cleanup.json", cleanup);
    const fileNames = (await readdir(out)).filter(
      (name) => name !== "manifest.json" && name !== "result.json",
    );
    const manifest = {
      schema: "loki.mac-computer-runner.private-evidence/1",
      taskId,
      createdAt: now(),
      files: await Promise.all(
        fileNames.sort().map(async (name) => ({
          path: name,
          bytes: (await stat(join(out, name))).size,
          sha256: sha256(await readFile(join(out, name))),
        })),
      ),
    };
    await save("manifest.json", manifest);
    const returnedInputs = actions.filter(
      (row) =>
        row.status === "returned" &&
        !["wait", "screenshot"].includes(row.action.type),
    ).length;
    const result = {
      taskId,
      outputDir: out,
      model,
      reasoning: config.reasoning ?? "low",
      target: { app: config.app, platform: "macOS", backend: "Appium Mac2" },
      terminal: redact.value(terminal),
      executionState:
        terminal.actor === "model"
          ? "completed"
          : terminal.actor === "operator"
            ? "cancelled"
            : terminal.actor === "harness"
              ? "blocked"
              : "unknown",
      testVerdict: "unverified",
      calls: calls.length,
      attemptedRequests: attempts,
      requestsWithoutUsage: attempts - calls.filter((row) => row.usage).length,
      returnedDesktopInputs: returnedInputs,
      axReads: axReads.length,
      elapsedMs: Date.now() - started,
      usage,
      estimatedCost,
      costPer10kInputs: returnedInputs
        ? (estimatedCost / returnedInputs) * 10000
        : null,
      costKind: "Usage-based estimate; unknown charges excluded",
      traceManifest: {
        path: join(out, "manifest.json"),
        sha256: sha256(await readFile(join(out, "manifest.json"))),
        files: manifest.files.length,
      },
      cleaned:
        cleanup.sessionDeleted &&
        cleanup.processClosed &&
        !cleanup.errors.length,
    };
    await save("result.json", result);
    progress({ result });
    summary = result;
  }
  return summary;
}

/** Integration envelope: IDs correlate, but scenario and parameters are always supplied. */
export async function run(input, options) {
  if (
    !input ||
    typeof input !== "object" ||
    !Object.hasOwn(input, "scenario") ||
    !Object.hasOwn(input, "params") ||
    !input.params ||
    typeof input.params !== "object" ||
    Array.isArray(input.params)
  )
    throw new TypeError("Full scenario and explicit params object required");
  if (!options?.apiKey && typeof options?.requestAI !== "function")
    throw new TypeError("Host-provided API key required");
  const scenario =
    typeof input.scenario === "string"
      ? input.scenario
      : JSON.stringify(input.scenario);
  const result = await runScenario({
    scenario,
    parameters: input.params,
    app: input.target?.app,
    launch: input.target?.launch,
    apiKey: options.apiKey,
    requestAI: options.requestAI,
    model: options.model,
    reasoning: options.reasoning,
    outputDir: options.artifactDirectory,
    signal: options.signal,
    onProgress: options.onEvent,
    secretParameterNames: options.secretParameterNames,
    limits: options.limits,
    taskId: input.requestId,
  });
  const correlated = {
    ...result,
    correlation: {
      requestId: input.requestId ?? null,
      scenarioId: input.scenarioId ?? null,
      planRef: input.planRef ?? null,
    },
  };
  await privateFile(join(result.outputDir, "result.json"), correlated);
  return correlated;
}
